head.script:
scwin.gNDV_NOTI_NO;
scwin.gNOTI_PROCS_STAT_CD; // 00:처리중, 10:검토, 20:승인
scwin.gPOP_GB; // N:입력, R:상세보기, P:검토/승인

scwin.gEmpNo = js_emp_no;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.initPage();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF00002.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_NdvNotiData_OnLoadCompleted
 * @description dts_NdvNotiData 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_NdvNotiData_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_NdvNotiData.errorMsg) {
            await $c.win.alert(dts_NdvNotiData.errorMsg);
        } else {
            txb_REVWR_EMP_NM.setValue(dts_NdvNotiData.getCellData(1, "REVWR_EMP_NM"));
            txb_REVW_DDTM.setValue(dts_NdvNotiData.getCellData(1, "REVW_DDTM"));
            txb_APPROVR_EMP_NM.setValue(dts_NdvNotiData.getCellData(1, "APPROVR_EMP_NM"));
            txb_APPROV_DDTM.setValue(dts_NdvNotiData.getCellData(1, "APPROV_DDTM"));
            txb_NDV_NOTI_TITLE.setValue(dts_NdvNotiData.getCellData(1, "NDV_NOTI_TITLE"));
            // setObjectValue(txb_NDV_NOTI_CONTN, dts_NdvNotiData.NameString(1, "NDV_NOTI_CONTN"));
            txa_NDV_NOTI_CONTN.Text = dts_NdvNotiData.getCellData(1, "NDV_NOTI_CONTN");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF00002.dts_NdvNotiData_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_NdvNotiData_OnLoadError
