    const sbmOptions = {
        id : "sbm_dts_NdvNotiData",
        action : "/NightNoti.do",
        ref : "",
        target : "dts_NdvNotiData=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getNowTime
 * @description get Now Time 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getNowTime = async function() {
    const sbmOptions = {
        id : "sbm_dts_now",
        action : "/NightNoti.do",
        ref : "",
        target : "dts_now=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} trIdx trIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trIdx) {
    let gJob;
    let gTrsCd;
    if (trIdx === "I") {
        gJob = '저장';
        gTrsCd = SCREN_PROCS_TP_CD_02;
    } else if (trIdx === "U") {
        gJob = '수정';
        gTrsCd = SCREN_PROCS_TP_CD_03;
    } else if (trIdx === "D") {
        gJob = '삭제';
        gTrsCd = SCREN_PROCS_TP_CD_04;
    } else if (trIdx === "R") {
        gJob = '검토';
        gTrsCd = SCREN_PROCS_TP_CD_03;
    } else if (trIdx === "A") {
        gJob = '승인';
        gTrsCd = SCREN_PROCS_TP_CD_03;
    } else if (trIdx === "J") {
        gJob = '반려';
        gTrsCd = SCREN_PROCS_TP_CD_03;
    }
    const vAnswer = window.confirm(gJob + " 하시겠습니까?");
    if (vAnswer === true) {
        // dts_single.NameString(1, "PROCS_GB") = trIdx;
        dts_single.setCellData(1, "NDV_NOTI_NO", txb_NDV_NOTI_NO.getValue());
        dts_single.setCellData(1, "LD_MKT_TP_CD", "3"); // 파생
        dts_single.setCellData(1, "NDV_NOTI_TITLE", txb_NDV_NOTI_TITLE.getValue());
        dts_single.setCellData(1, "NDV_NOTI_CONTN", txa_NDV_NOTI_CONTN.Text);
        dts_single.setCellData(1, "EMP_NO", scwin.gEmpNo);
        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     PROCS_GB : trIdx
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/NightNoti.do",
            ref : "dts_single",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initPage = async function() {
    panel_debug.hide();
    await scwin.setCode();
    scwin.gNDV_NOTI_NO = $c.stf.getQuery(frame.srcUrl, "NDV_NOTI_NO");
    scwin.gNOTI_PROCS_STAT_CD = $c.stf.getQuery(frame.srcUrl, "NOTI_PROCS_STAT_CD");
    scwin.gPOP_GB = $c.stf.getQuery(frame.srcUrl, "POP_GB");
    await scwin.search();
    if (scwin.gPOP_GB === "N") {
        panel_1.show("");
        panel_2.hide();
        panel_3.hide();
        txb_NDV_NOTI_TITLE.setValue("(야간파생상품시장 공지)");
    } else if (scwin.gPOP_GB === "R") {
        panel_1.hide();
        panel_2.hide();
        panel_3.hide();
    } else if (scwin.gPOP_GB === "P") {
        if (scwin.gNOTI_PROCS_STAT_CD === "00") {
            panel_1.hide();
            panel_2.show("");
            panel_3.hide();
        } else if (scwin.gNOTI_PROCS_STAT_CD === "10") {
            panel_1.hide();
            panel_2.hide();
            panel_3.show("");
        }
    }
    await scwin.getNowTime();
};

/**
 * @method
 * @name checkValue
 * @description check Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValue = async function() {
    if (txb_NDV_NOTI_TITLE.getValue() === "") {
        await $c.win.alert("[제목]을 입력하세요.");
        txb_NDV_NOTI_TITLE.focus();
        return false;
    }
    if (txa_NDV_NOTI_CONTN.Text === "") {
        await $c.win.alert("[내용]을 입력하세요.");
        txa_NDV_NOTI_CONTN.focus();
        return false;
    }
    if (txb_NDV_NOTI_TITLE.getValue() !== "") {
        if (!$c.stf.checkMaxLength(txb_NDV_NOTI_TITLE, 1000, "제목")) return false;
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkValue()) {
        await scwin.trs("I");
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (await scwin.checkValue()) {
        await scwin.trs("U");
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    await scwin.trs("D");
};

/**
 * @method
 * @name review
 * @description review 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.review = async function() {
    if (await scwin.checkValue()) {
        await scwin.trs("R");
    }
};

/**
 * @method
 * @name approval
 * @description approval 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.approval = async function() {
    // 승인가능시간 (20:00 ~ 07:30)
    await scwin.getNowTime();
    // alert(getObjectValue(txb_nowtime));

    if (txb_nowtime.getValue() < "200000" && txb_nowtime.getValue() >= "073000") {
        await $c.win.alert("승인가능시간 (20:00 ~ 07:30)");
        return false;
    }
    if (await scwin.checkValue()) {
        await scwin.trs("A");
    }
};

/**
 * @method
 * @name reject
 * @description reject 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reject = async function() {
    if (await scwin.checkValue()) {
        await scwin.trs("J");
    }
};

/**
 * @method
 * @name newLine
 * @description new line
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.newLine = function(str) {
    if (str === "") return "";
    return str.replace(/\r\n/g, "<br/>");
};
